create extension if not exists pgcrypto;
create table if not exists public.leads(id uuid primary key default gen_random_uuid(),name text not null check(char_length(name) between 2 and 100),company text,email text not null check(char_length(email)<=254),phone text,service text not null check(service in('web','seo','both','other')),budget text,message text not null check(char_length(message) between 20 and 4000),status text not null default 'new' check(status in('new','contacted','negotiation','won','lost','archived')),source text not null default 'website',consent_at timestamptz not null,internal_notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.projects(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,description text not null,category text not null default 'Proyecto propio',image_url text,gallery text[] not null default '{}',external_url text,published boolean not null default false,sort_order int not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.services(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,description text not null,content text,meta_title text,meta_description text,published boolean not null default false,sort_order int not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.site_settings(id int primary key default 1 check(id=1),business_name text not null default 'Lazo Sur',description text,contact_email text,phone text,whatsapp text,social_links jsonb not null default '{}'::jsonb,canonical_url text,seo_title text,seo_description text,og_image text,footer_text text,updated_at timestamptz not null default now());
create table if not exists public.admin_audit_log(id uuid primary key default gen_random_uuid(),actor_email text not null,action text not null,entity text not null,entity_id text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
alter table public.leads enable row level security;alter table public.projects enable row level security;alter table public.services enable row level security;alter table public.site_settings enable row level security;alter table public.admin_audit_log enable row level security;
create policy "published projects are public" on public.projects for select to anon,authenticated using(published=true);create policy "published services are public" on public.services for select to anon,authenticated using(published=true);grant select on public.projects,public.services to anon,authenticated;
insert into public.projects(name,slug,description,category,published,sort_order) values('MétricaSur','metricasur','Proyecto propio de software de gestión y analítica empresarial.','Proyecto propio',true,1),('RadioEterna','radioeterna','Proyecto digital propio de Lazo Sur.','Proyecto propio',true,2) on conflict(slug) do nothing;
insert into public.services(name,slug,description,published,sort_order) values('Diseño y desarrollo web','desarrollo-web','Sitios institucionales, landing pages y desarrollos a medida.',true,1),('Posicionamiento SEO','seo','Auditoría, SEO técnico, contenidos y estrategia orgánica.',true,2) on conflict(slug) do nothing;